    const int grid_size = (n + block_size - 1) / block_size;
    gelu_kernel&lt;&lt;&lt;grid_size, block_size&gt;&gt;&gt;(input.data_ptr&lt;float&gt;(), output.data_ptr&lt;float&gt;(), static_cast&lt;int&gt;(n));
