#include &lt;hip/hip_runtime.h&gt;

__global__ void batched_matmul_kernel(const float *A, const float *B, float *C, int batch_size, int M, int N, int K) {
    int batch = blockIdx.z;
    if (batch &gt;= batch_size) return;

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row &lt; M &amp;&amp; col &lt; N) {
        const float* a_batch = A + batch * M * K;
        const float* b_batch = B + batch * K * N;
        float sum = 0.0f;
        for (int i = 0; i &lt; K; ++i) {
            sum += a_batch[row * K + i] * b_batch[i * N + col];
        }
        C[batch * M * N + row * N + col] = sum;
    }
}

torch::Tensor batched_matmul_hip(torch::Tensor A, torch::Tensor B) {
    int64_t batch_size = A.size(0);
    int64_t M = A.size(1);
    int64_t K = A.size(2);
    int64_t N = B.size(2);

    torch::Tensor C = torch::zeros({batch_size, M, N}, A.options());

    const int TILE_SIZE = 32;
    dim3 blockDim(TILE_SIZE, TILE_SIZE);
    dim3 gridDim((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE, (int)batch_size);

    batched_matmul_kernel&lt;&lt;&lt;gridDim, blockDim&gt;&gt;&gt;(A.data_ptr&lt;float&gt;(), B.data_ptr&lt;float&gt;(), C.data_ptr&lt;float&gt;(), (int)batch_size, (int)M, (int)N, (int)K);

    return C;
}
"""

