matmul_cpp = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

__global__ void matmul_kernel(const float *A, const float *B, float *C, int M, int N, int K) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    const int TILE_SIZE = 16;
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;
    float acc = 0.0f;
    int num_tiles = (K + TILE_SIZE - 1) / TILE_SIZE;
    for (int ph = 0; ph &lt; num_tiles; ++ph) {
        As[ty][tx] = (row &lt; M &amp;&amp; ph * TILE_SIZE + tx &lt; K) ? A[row * K + ph * TILE_SIZE + tx] : 0.0f;
        Bs[ty][tx] = (col &lt; N &amp;&amp; ph * TILE_SIZE + ty &lt; K) ? B[(ph * TILE_SIZE + ty) * N + col] : 0.0f;
        __syncthreads();
        #pragma unroll
        for (int i = 0; i &lt; TILE_SIZE; ++i) {
            acc += As[ty][i] * Bs[i][tx];
        }
        __syncthreads();
    }
    if (row &lt; M &amp;&amp; col &lt; N) {
        C[row * N + col] = acc;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);
    CHECK_CUDA(A);
    CHECK_CONTIGUOUS(A);
    CHECK_CUDA(B);
    CHECK_CONTIGUOUS(B);
    torch::Tensor out = torch::zeros({M, N}, A.options());
    const int TILE_SIZE = 16;
    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);
    matmul_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(A.data_ptr&lt;float&gt;(), B.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), (int)M, (int)N, (int)K);
    return out;
}
"""

matmul_ext = load_inline(
    name="matmul",
    cpp_sources=matmul_cpp,
    functions=["matmul_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
