#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

__global__ void sgemm_naive(const float* A_global, const float* B_global, float* C_global, const int M, const int N, const int K) {
    const int TPBX = 16;
    const int TPBY = 16;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TPBY + ty;
    int col = blockIdx.x * TPBX + tx;
    if (row &lt; M &amp;&amp; col &lt; N) {
        float sum = 0.0f;
        for (int k = 0; k &lt; K; k++) {
            sum += A_global[row * K + k] * B_global[k * N + col];
        }
        C_global[row * N + col] = sum;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int64_t M_ = A.size(0);
    int64_t K_ = A.size(1);
    int64_t N_ = B.size(1);
    int M = static_cast&lt;int&gt;(M_);
    int K = static_cast&lt;int&gt;(K_);
    int N = static_cast&lt;int&gt;(N_);
    auto C = torch::zeros({M_, N_}, A.options());
    const int TPBX = 16;
    const int TPBY = 16;
    dim3 block(TPBX, TPBY);
    dim3 grid((N + TPBX - 1) / TPBX, (M + TPBY - 1) / TPBY);
    hipLaunchKernelGGL(sgemm_naive, grid, block, 0, 0, A.data_ptr&lt;float&gt;(), B.data_ptr&lt;float&gt;(), C.data_ptr&lt;float&gt;(), M, N, K);
    return C;
