matmul_cpp_source = r'''
#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
  int64_t m = A.size(0);
  int64_t k = A.size(1);
  int64_t n = B.size(1);
  TORCH_CHECK(k == B.size(0), "matmul: input shapes don't match");

  auto options = A.options();
  torch::Tensor C = torch::zeros({m, n}, options);

  const int TS = 16;
  dim3 block(TS, TS);
  dim3 grid((n + TS - 1) / TS, (m + TS - 1) / TS);

  sgemm&lt;&lt;&lt;grid, block&gt;&gt;&gt;(A.data_ptr&lt;float&gt;(), B.data_ptr&lt;float&gt;(), C.data_ptr&lt;float&gt;(), (int)m, (int)n, (int)k);

  return C;
}

__global__ void sgemm(const float *A, const float *B, float *C, int M, int N, int K) {
  const int row = blockIdx.y * 16 + threadIdx.y;
  const int col = blockIdx.x * 16 + threadIdx.x;
  float sum = 0.0f;
  if (row &lt; M &amp;&amp; col &lt; N) {
    for (int tile_k = 0; tile_k &lt; K; tile_k++) {
      sum += A[row * K + tile_k] * B[tile_k * N + col];
    }
    C[row * N + col] = sum;
  }
}
'''

