__global__ void rmsnorm_fused_kernel(const float* __restrict__ x, float* __restrict__ out, int N, int C, int H, int W, float eps) {
    unsigned int pos_id = blockIdx.x;
    int hw = H * W;
    int n = pos_id / hw;
    int rem = pos_id % hw;
    int h = rem / W;
    int w = rem % W;

    extern __shared__ float sdata[];

    unsigned int tid = threadIdx.x;
    float val = 0.0f;
    if (tid &lt; (unsigned int)C) {
        int idx = ((n * C + (int)tid) * H + h) * W + w;
        val = x[idx];
        sdata[tid] = val * val;
    } else {
        sdata[tid] = 0.0f;
    }
    __syncthreads();

    for (int offset = C / 2; offset &gt; 0; offset /= 2) {
        if (tid &lt; (unsigned int)offset) {
            sdata[tid] += sdata[tid + offset];
