#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;
#include &lt;cmath&gt;

__global__ void rmsnorm_fused_kernel(const float* __restrict__ x, float* __restrict__ out, int N, int C, int H, int W, float eps) {
    unsigned int pos_id = blockIdx.x;
    int hw = H * W;
    int n = pos_id / hw;
    int rem = pos_id % hw;
    int h = rem / W;
    int w = rem % W;

    extern __shared__ float sdata[];

    unsigned int tid = threadIdx.x;
    float val = 0.0f;
    if (tid &lt; (unsigned int)C) {
        int idx = ((n * C + (int)tid) * H + h) * W + w;
        val = x[idx];
        sdata[tid] = val * val;
    } else {
        sdata[tid] = 0.0f;
    }
    __syncthreads();

    int coffset = C / 2;
    for (int offset = coffset; offset &gt; 0; offset /= 2) {
        if (tid &lt; (unsigned int)offset) {
            sdata[tid] += sdata[tid + offset];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float rms_val = sqrtf(sdata[0] / static_cast&lt;float&gt;(C) + eps);
        sdata[0] = rms_val;
    }
    __syncthreads();

    float rms = sdata[0];

    if (tid &lt; (unsigned int)C) {
        int idx = ((n * C + (int)tid) * H + h) * W + w;
        out[idx] = val / rms;
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor x, float eps) {
    TORCH_CHECK(x.dim() == 4, "Input must be 4D tensor");
    auto out = torch::empty_like(x);
    int64_t N_ = x.size(0);
    int64_t C_ = x.size(1);
    int64_t H_ = x.size(2);
    int64_t W_ = x.size(3);
    int N = static_cast&lt;int&gt;(N_);
    int C = static_cast&lt;int&gt;(C_);
    int H = static_cast&lt;int&gt;(H_);
    int W = static_cast&lt;int&gt;(W_);
    int64_t num_pos_ = N_ * H_ * W_;
    TORCH_CHECK(num_pos_ &lt;= std::numeric_limits&lt;int&gt;::max(), "Too many positions");
    int num_pos = static_cast&lt;int&gt;(num_pos_);
    const int block_size = 256;
    dim3 block(block_size);
    dim3 grid(num_pos);
    size_t shared_mem = static_cast&lt;size_t&gt;(block_size) * sizeof(float);
    rmsnorm_fused_kernel&lt;&lt;&lt;grid, block, shared_mem&gt;&gt;&gt;(x.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), N, C, H, W, eps);
