    CHECK_INPUT(A);
    CHECK_INPUT(B);

    const int64_t M = A.size(0);
    const int64_t K_ = A.size(1);
    const int64_t N_ = B.size(1);
    const int TM = 128;
    const int TN = 128;

    auto C = torch::empty({M, N_}, A.options());

    const dim3 blocks(
        (N_ + TN - 1) / TN,
        (M + TM - 1) / TM
    );
    const dim3 threads(16, 16);

    const size_t shmem_bytes = ((size_t)TM * K_ + (size_t)K_ * TN) * sizeof(float);

