        gemm_kernel,
        blocks,
        threads,
        shmem_bytes,
        0,
        A.data_ptr&lt;float&gt;(),
        B.data_ptr&lt;float&gt;(),
        C.data_ptr&lt;float&gt;(),
        M,
        N_,
        K_,
        TM,
        TN
    );

    return C;
}
