        grid_dims,
        block_dims,
        0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        int(N), int(Cin), int(Cout), int(Hin), int(Win), int(Hout), int(Wout), int(K)
    );

    return output;
}
