__global__ void row_max_kernel(const float *x, float *maxes, int B, int D) {
    int row = blockIdx.x;
    if (row >= B) return;
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int bs = blockDim.x;
    float lmax = -1e30f;
    int offset = row * D;
    for (int i = tid; i < D; i += bs) {
        float v = x[offset + i];
        lmax = fmaxf(lmax, v);
    }
    sdata[tid] = lmax;
    __syncthreads();
    for (int s = bs / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }
    if (tid == 0) {
        maxes[row] = sdata[0];
    }
