__global__ void row_exp_sum_kernel(const float *x, const float *maxes, float *sums, int B, int D) {
    int row = blockIdx.x;
    if (row >= B) return;
    float mmax = maxes[row];
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int bs = blockDim.x;
    float lsum = 0.0f;
    int offset = row * D;
    for (int i = tid; i < D; i += bs) {
        float v = x[offset + i] - mmax;
        lsum += (v < -30.0f) ? 0.0f : expf(v);
    }
    sdata[tid] = lsum;
    __syncthreads();
    for (int s = bs / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        sums[row] = sdata[0];
    }
}

__global__ void row_scale_kernel(const float *x, const float *maxes, const float *sums, float *out, int B, int D) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * D) return;
    int row = idx / D;
    int col = idx % D;
    float mmax = maxes[row];
    float v = x[idx] - mmax;
    float expv = (v < -30.0f) ? 0.0f : expf(v);
    out[idx] = expv / sums[row];
}

