#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <limits>

__global__ void rmsnorm_fused_kernel(const float* __restrict__ x, float* __restrict__ out, int N, int C, int H, int W, float eps) {
    unsigned int pos_id = blockIdx.x;
    int hw = H * W;
    int n = pos_id / hw;
    int rem = pos_id % hw;
    int h = rem / W;
    int w = rem % W;

    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    float val = 0.0f;
    if (tid < C) {
        int idx = ((n * C + tid) * H + h) * W + w;
        val = x[idx];
        sdata[tid] = val * val;
    } else {
        sdata[tid] = 0.0f;
    }
    __syncthreads();

    for (int offset = C / 2; offset > 0; offset /= 2) {
        if (tid < offset) {
            sdata[tid] += sdata[tid + offset];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float rms_val = sqrtf(sdata[0] / static_cast<float>(C) + eps);
        sdata[0] = rms_val;
    }
    __syncthreads();

    float rms = sdata[0];

    if (tid < C) {
        int idx = ((n * C + tid) * H + h) * W + w;
        out[idx] = val / rms;
    }
}

