    int64_t W_ = x.size(3);
    int N = static_cast<int>(N_);
    int C = static_cast<int>(C_);
    int H = static_cast<int>(H_);
    int W = static_cast<int>(W_);
    int64_t num_pos_ = N_ * H_ * W_;
    TORCH_CHECK(num_pos_ <= std::numeric_limits<int64_t>::max(), "Too many positions");
    int num_pos = static_cast<int>(num_pos_);
    const int block_size = 256;
    dim3 block(block_size);
    dim3 grid(num_pos);
    size_t shared_mem = static_cast<size_t>(block_size) * sizeof(float);
    rmsnorm_fused_kernel<<<grid, block, shared_mem>>>(x.data_ptr<float>(), out.data_ptr<float>(), N, C, H, W, eps);
