#include <hip/hip_runtime.h>

__global__ void depthwise_conv2d_kernel(const float *input, int B, int C, int H, int W, const float *weight, int K, float *output, int Ho, int Wo, int S, int P) {
  int tx = threadIdx.x;
  int ty = threadIdx.y;
  int oh = blockIdx.x * blockDim.x + tx;
  int ow = blockIdx.y * blockDim.y + ty;
  int bc = blockIdx.z;
  if (oh >= Ho || ow >= Wo) return;
  int b = bc / C;
  int c = bc % C;
  float sum = 0.0f;
  for (int kh = 0; kh < K; ++kh) {
    int ih = S * oh + kh - P;
    if (ih < 0 || ih >= H) continue;
    for (int kw = 0; kw < K; ++kw) {
      int iw = S * ow + kw - P;
      if (iw < 0 || iw >= W) continue;
      int iidx = ((b * C + c) * H + ih) * W + iw;
      int widx = c * K * K + kh * K + kw;
      sum += input[iidx] * weight[widx];
    }
  }
  int oidx = ((b * C + c) * Ho + oh) * Wo + ow;
  output[oidx] = sum;
}

torch::Tensor depthwise_conv2d_hip(torch::Tensor input, torch::Tensor weight, int stride, int pad) {
  int B = input.size(0);
  int C = input.size(1);
  int H = input.size(2);
  int W = input.size(3);
  int K = weight.size(2);
  int Ho = (H + 2 * pad - K) / stride + 1;
  int Wo = (W + 2 * pad - K) / stride + 1;
  auto out = torch::empty({B, C, Ho, Wo}, input.options());
  const int TX = 32;
  const int TY = 8;
  dim3 threads(TX, TY);
  dim3 blocks((Ho + TX - 1) / TX, (Wo + TY - 1) / TY, B * C);
  depthwise_conv2d_kernel<<<blocks, threads>>>(input.data_ptr<float>(), B, C, H, W, weight.data_ptr<float>(), K, out.data_ptr<float>(), Ho, Wo, stride, pad);
  return out;
}
