#include <hip/hip_runtime.h>
#include <cmath>

__global__ void gelu_kernel(const float *input, float *output, size_t n) {
    size_t idx4 = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
    size_t idx = idx4 * 4;
    if (idx + 3 < n) {
        const float kErfApproxB1 = 0.707106781186547524400844362104849f;
        float x0 = input[idx];
        float x1 = input[idx + 1];
        float x2 = input[idx + 2];
        float x3 = input[idx + 3];
        float erf0 = erf(x0 * kErfApproxB1);
        float erf1 = erf(x1 * kErfApproxB1);
        float erf2 = erf(x2 * kErfApproxB1);
        float erf3 = erf(x3 * kErfApproxB1);
        output[idx] = 0.5f * x0 * (1.0f + erf0);
        output[idx + 1] = 0.5f * x1 * (1.0f + erf1);
        output[idx + 2] = 0.5f * x2 * (1.0f + erf2);
        output[idx + 3] = 0.5f * x3 * (1.0f + erf3);
    }
}

