    const int block_size = 256;
    const int items_per_thread = 4;
    int64_t num_threads = (n + items_per_thread - 1) / items_per_thread;
    int grid_size = (num_threads + block_size - 1) / block_size;
    gelu_kernel<<<grid_size, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), static_cast<size_t>(n));
