#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void row_max_kernel(const float *x, float *maxes, int B, int D) {
    int row = blockIdx.x;
    if (row >= B) return;
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int bs = blockDim.x;
    float lmax = -1e30f;
    int offset = row * D;
    for (int i = tid; i < D; i += bs) {
        float v = x[offset + i];
        lmax = fmaxf(lmax, v);
    }
    sdata[tid] = lmax;
    __syncthreads();
    for (int s = bs / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }
    if (tid == 0) {
        maxes[row] = sdata[0];
    }
}

__global__ void row_exp_sum_kernel(const float *x, const float *maxes, float *exps, float *sums, int B, int D) {
    int row = blockIdx.x;
    if (row >= B) return;
    float mmax = maxes[row];
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int bs = blockDim.x;
    float lsum = 0.0f;
    int offset = row * D;
    for (int i = tid; i < D; i += bs) {
        float v = x[offset + i] - mmax;
        float expv = (v < -30.0f) ? 0.0f : expf(v);
        exps[offset + i] = expv;
        lsum += expv;
    }
    sdata[tid] = lsum;
    __syncthreads();
    for (int s = bs / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        sums[row] = sdata[0];
    }
}

__global__ void row_scale_kernel(const float *exps, const float *sums, float *out, int B, int D) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * D) return;
    int row = idx / D;
    out[idx] = exps[idx] / sums[row];
}

torch::Tensor softmax_hip(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");
    auto num_rows_long = x.size(0);
