    const int bs = 256;
    dim3 block(bs);
    dim3 grid(B);
    size_t shmem_size = bs * sizeof(float);
    hipLaunchKernelGGL(row_max_kernel, grid, block, shmem_size, 0, x.data_ptr<float>(), row_max.data_ptr<float>(), B, D);
