    long long total = (long long)B * D;
    dim3 grid_scale(static_cast<unsigned int>((total + bs - 1) / bs));
    hipLaunchKernelGGL(row_scale_kernel, grid_scale, block, 0, 0, exps.data_ptr<float>(), row_sums.data_ptr<float>(), out.data_ptr<float>(), B, D);
