#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void conv2d_naive_kernel(
    const float *input, 
    const float *weight, 
    float *output, 
    int N, int Cin, int Cout, int Hin, int Win, int Hout, int Wout, int K
) {
    unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= static_cast<unsigned int>(N * Cout * Hout * Wout)) return;
    int n = idx / (Cout * Hout * Wout);
    int temp = idx % (Cout * Hout * Wout);
    int cout_idx = temp / (Hout * Wout);
    int h_idx = (temp % (Hout * Wout)) / Wout;
    int w_idx = temp % Wout;
    float sum = 0.0f;
    for (int c = 0; c < Cin; c++) {
        int input_c_offset = (n * Cin + c) * Hin * Win;
        int weight_c_offset = (cout_idx * Cin + c) * K * K;
        for (int kh = 0; kh < K; kh++) {
            int h = h_idx + kh;
            if (h >= Hin) continue;
            int input_h_offset = input_c_offset + h * Win;
            int weight_kh_offset = weight_c_offset + kh * K;
            for (int kw = 0; kw < K; kw++) {
                int w = w_idx + kw;
                if (w >= Win) continue;
                sum += input[ input_h_offset + w ] * weight[ weight_kh_offset + kw ];
            }
        }
    }
    output[idx] = sum;
}

torch::Tensor conv2d_hip(torch::Tensor input, torch::Tensor weight) {
    int64_t N = input.size(0);
    int64_t Cin = input.size(1);
    int64_t Hin = input.size(2);
    int64_t Win = input.size(3);
    int64_t Cout = weight.size(0);
    int64_t K = weight.size(3);
    int64_t Hout = Hin - K + 1;
    int64_t Wout = Win - K + 1;

    if (Hout <= 0 || Wout <= 0) {
        return torch::zeros({N, Cout, 0, 0}, input.options());
    }

    auto output = torch::empty({N, Cout, Hout, Wout}, input.options());

    const int threads = 1024;
    size_t num_elements = static_cast<size_t>(N) * static_cast<size_t>(Cout) * static_cast<size_t>(Hout) * static_cast<size_t>(Wout);
    size_t num_blocks_ = (num_elements + threads - 1ULL) / threads;
    dim3 block_dims(threads);
    dim3 grid_dims(static_cast<uint32_t>(num_blocks_));

    hipLaunchKernelGGL(
        HIP_KERNEL_NAME(conv2d_naive_kernel),
        grid_dims,
        block_dims,
        0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        static_cast<int>(N), static_cast<int>(Cin), static_cast<int>(Cout), 
        static_cast<int>(Hin), static_cast<int>(Win), static_cast<int>(Hout), static_cast<int>(Wout), static_cast<int>(K)
    );

    return output;
}
"""

