matmul_cpp = '''
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void sgemm_tiled(const float *__restrict__ A_global, const float *__restrict__ B_global, float *__restrict__ C_global, const int M, const int N, const int K) {
    const int TILE_DIM = 32;
    extern __shared__ float shmem[];
    float *As = shmem;
    float *Bs = As + TILE_DIM * TILE_DIM;
    int Row = blockIdx.y * TILE_DIM + threadIdx.y;
    int Col = blockIdx.x * TILE_DIM + threadIdx.x;
    float Pvalue = 0.0f;
    const int num_tiles = K / TILE_DIM;
    for (int m = 0; m < num_tiles; ++m) {
        __syncthreads();
        if (Row < M && (m * TILE_DIM + threadIdx.x) < K) {
            As[threadIdx.y * TILE_DIM + threadIdx.x] = A_global[Row * K + m * TILE_DIM + threadIdx.x];
        } else {
            As[threadIdx.y * TILE_DIM + threadIdx.x] = 0.0f;
        }
        if (Col < N && (m * TILE_DIM + threadIdx.y) < K) {
            Bs[threadIdx.y * TILE_DIM + threadIdx.x] = B_global[(m * TILE_DIM + threadIdx.y) * N + Col];
        } else {
            Bs[threadIdx.y * TILE_DIM + threadIdx.x] = 0.0f;
        }
        __syncthreads();
        for (int k = 0; k < TILE_DIM; ++k) {
            Pvalue += As[threadIdx.y * TILE_DIM + k] * Bs[k * TILE_DIM + threadIdx.x];
        }
    }
    if (Row < M && Col < N) {
        C_global[Row * N + Col] = Pvalue;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int64_t M_ = A.size(0);
    int64_t K_ = A.size(1);
    int64_t N_ = B.size(1);
    int M = static_cast<int>(M_);
    int K = static_cast<int>(K_);
    int N = static_cast<int>(N_);
    auto C = torch::zeros({M_, N_}, A.options());
    const int TILE_DIM = 32;
    dim3 block(TILE_DIM, TILE_DIM);
    dim3 grid((N + TILE_DIM - 1) / TILE_DIM, (M + TILE_DIM - 1) / TILE_DIM);
    size_t shmem_bytes = 2ULL * TILE_DIM * TILE_DIM * sizeof(float);
    hipLaunchKernelGGL(sgemm_tiled, grid, block, shmem_bytes, 0, A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);
    return C;
}
