__global__ void sgemm_tiled(const float *__restrict__ A_global, const float *__restrict__ B_global, float *__restrict__ C_global, const int M, const int N, const int K) {
    const int TILE_DIM = 32;
    extern __shared__ float shmem[];
    float *As = shmem;
    float *Bs = As + TILE_DIM * TILE_DIM;
    int Row = blockIdx.y * TILE_DIM + threadIdx.y;
    int Col = blockIdx.x * TILE_DIM + threadIdx.x;
    float Pvalue = 0.0f;
    const int num_tiles = (K + TILE_DIM - 1) / TILE_DIM;
    for (int m = 0; m < num_tiles; ++m) {
        __syncthreads();
        if (Row < M && (m * TILE_DIM + threadIdx.x) < K) {
            As[threadIdx.y * TILE_DIM + threadIdx.x] = A_global[Row * K + m * TILE_DIM + threadIdx.x];
        } else {
            As[threadIdx.y * TILE_DIM + threadIdx.x] = 0.0f;
        }
        if (Col < N && (m * TILE_DIM + threadIdx.y) < K) {
            Bs[threadIdx.y * TILE_DIM + threadIdx.x] = B_global[(m * TILE_DIM + threadIdx.y) * N + Col];
