#include <hip/hip_runtime.h>

__global__ void matmul_kernel(const float *A, const float *B, float *C, int M, int N, int K) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    const int TS = 32;
    __shared__ float As[2][TS][TS];
    __shared__ float Bs[2][TS][TS];
    int row = by * TS + ty;
    int col = bx * TS + tx;
    float acc = 0.0f;
    const int nTiles = (K + TS - 1) / TS;

    int current = 0;
    // load first tile block
    As[current][ty][tx] = (row < M && tx < K) ? A[row * K + tx] : 0.0f;
    Bs[current][ty][tx] = (col < N && ty < K) ? B[ty * N + col] : 0.0f;
    __syncthreads();
    // compute first tile
    #pragma unroll
    for (int i = 0; i < TS; ++i) {
        acc += As[current][ty][i] * Bs[current][i][tx];
    }

    for (int ph = 1; ph < nTiles; ++ph) {
        current = 1 - current;
        As[current][ty][tx] = (row < M && ph * TS + tx < K) ? A[row * K + ph * TS + tx] : 0.0f;
        Bs[current][ty][tx] = (col < N && ph * TS + ty < K) ? B[(ph * TS + ty) * N + col] : 0.0f;
        __syncthreads();
        #pragma unroll
        for (int i = 0; i < TS; ++i) {
            acc += As[current][ty][i] * Bs[current][i][tx];
        }
    }
    if (row < M && col < N) {
        C[row * N + col] = acc;
    }
}

torch::Tensor matmul_hip(torch::Tensor a, torch::Tensor b) {
    int64_t M = a.sizes()[0];
    int64_t K = a.sizes()[1];
    int64_t N = b.sizes()[1];
    torch::Tensor c = torch::zeros({M, N}, a.options());
    const int TS = 32;
    dim3 block(TS, TS);
    dim3 grid((N + TS - 1) / TS, (M + TS - 1) / TS);
    matmul_kernel<<<grid, block>>>(a.data_ptr<float>(), b.data_ptr<float>(), c.data_ptr<float>(), (int)M, (int)N, (int)K);
    return c;
}
