  constexpr int TS = 32;
  __shared__ float sh_As[2][TS][TS];
  __shared__ float sh_Bs[2][TS][TS];

  const int by = blockIdx.y;
  const int bx = blockIdx.x;
  const int ty = threadIdx.y;
  const int tx = threadIdx.x;

  float acc = 0.0f;
  const int ktile_max = (K + TS - 1) / TS;
  int buf_idx = 0;

