    int row_a = by * TS + ty;
    int col_a = kz_load * TS + tx;
    sh_As[buf_idx][ty][tx] = (row_a < M && col_a < K) ? A[row_a * K + col_a] : 0.0f;

    int row_b = kz_load * TS + ty;
    int col_b = bx * TS + tx;
    sh_Bs[buf_idx][ty][tx] = (row_b < K && col_b < N) ? B[row_b * N + col_b] : 0.0f;
