matmul_cpp = """
#include <hip/hip_runtime.h>

__global__ void matmul_kernel(const float *A, const float *B, float *C, int M, int N, int K) {
    const int TM = 32;
    const int TN = 32;
    const int TK = 128;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    __shared__ float As[TM][TK];
    __shared__ float Bs[TK][TN];
    int row = by * TM + ty;
    int col = bx * TN + tx;
    float acc = 0.0f;
    int num_tiles = (K + TK - 1) / TK;
    for (int ph = 0; ph < num_tiles; ++ph) {
        // Load A tile
        #pragma unroll
        for (int kk = 0; kk < TK / TM; ++kk) {
            int lk = kk * TM + tx;
            As[ty][lk] = (row < M && ph * TK + lk < K) ? A[row * K + ph * TK + lk] : 0.0f;
        }
        // Load B tile
        #pragma unroll
        for (int kk = 0; kk < TK / TN; ++kk) {
            int lk = kk * TN + ty;
            Bs[lk][tx] = (col < N && ph * TK + lk < K) ? B[(ph * TK + lk) * N + col] : 0.0f;
        }
        __syncthreads();
        // Compute
        for (int k = 0; k < TK; ++k) {
            acc += As[ty][k] * Bs[k][tx];
        }
        // No syncthreads here!
    }
    if (row < M && col < N) {
        C[row * N + col] = acc;
    }
}

