    const int TN = 32;
    dim3 block(TN, TM);
    dim3 grid((NN + TN - 1) / TN, (MM + TM - 1) / TM);
    matmul_kernel<<<grid, block>>>(a.data_ptr<float>(), b.data_ptr<float>(), c.data_ptr<float>(), (int)MM, (int)NN, (int)KK);
    return c;
}
